/** Declarative scenarios projected by Python; all journeys use the one gateway. */
import type {Page} from '@playwright/test';
import {
  type Journey,
  journeyFixture,
  journeyReplay,
  journeyTransition,
  journeyUpdate,
  type NativeJourney,
} from '../src/testing/journey-records.js';
import {nativeReplayScript} from './native-fixture.js';

export {
  type Journey,
  journeyFixture,
  journeyHead,
  type NativeJourney,
} from '../src/testing/journey-records.js';

/** A native replay generated by Python, never TypeScript-authored spans or a second gateway Fake. */
export function journeyScript(name: Journey): string {
  return nativeReplayScript(
    journeyFixture(name),
    journeyReplay(name === 'live' ? 'live.initial' : name),
  );
}

/** Deliver the next native records and stream writes, in the original source order. */
export async function appendJourney(page: Page, after: number, through: number): Promise<void> {
  for (let sequence = after + 1; sequence <= through; sequence += 1) {
    await page.evaluate(({tail, streams, hasRecords}) => {
      const peer = (
        window as unknown as {
          fakeGateway: {
            append(bytes: number[]): void;
            appendStreams(streams: Record<string, number[]>): void;
          };
        }
      ).fakeGateway;
      if (hasRecords) peer.append(tail);
      peer.appendStreams(streams);
    }, journeyUpdate(sequence));
  }
}

/** The real skeleton builder appends the requested lifecycle after this scenario's prefix. */
export async function transitionJourney(
  page: Page,
  from: NativeJourney,
  to: NativeJourney,
): Promise<void> {
  await page.evaluate(
    bytes =>
      (window as unknown as {fakeGateway: {append(bytes: number[]): void}}).fakeGateway.append(
        bytes,
      ),
    journeyTransition(from, to),
  );
}
